ANALYZE foo;

ANALYSE foo;

ANALYZE VERBOSE foo;

ANALYZE (VERBOSE, SKIP_LOCKED) foo;

ANALYZE (VERBOSE FALSE, SKIP_LOCKED TRUE) foo;

ANALYZE (SKIP_LOCKED, VERBOSE FALSE) foo;

ANALYZE VERBOSE foo (bar, bat);

ANALYZE foo (bar, bat), foo2 (bar2, bat2);

ANALYZE (VERBOSE ON, SKIP_LOCKED OFF) foo;

ANALYZE (VERBOSE 1, SKIP_LOCKED 0) foo;

ANALYZE (BUFFER_USAGE_LIMIT 256) foo;

ANALYZE (BUFFER_USAGE_LIMIT '1MB', VERBOSE) foo;
